import sys
from collections import Counter

def count_frequency(elements):
    freq = Counter(elements)
    for elem in freq:
        print(f"{elem} -> {freq[elem]}")

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    elements = data[1:n+1]
    count_frequency(elements)

if __name__ == "__main__":
    main()
